await check('visual_table_selection_fallback_list_and_raw_preserve_unselected_data',async()=>{for(const c of [{kind:'selected',source:'**앞** 선택 *뒤*\n\n끝\n'},{kind:'fallback',source:'선택 밖 원문\n\n끝\n'},{kind:'list',source:'- 첫 항목\n- 둘째 항목\n\n끝\n'},{kind:'raw',source:'<custom>원문 **별표**</custom>\n'},{kind:'code',source:'```text\n원문 코드\n```\n'}]){await sourceFill(c.source);await page.getByRole('button',{name:'서식 편집',exact:true}).click();await page.locator('.rich-editor').evaluate((node,c)=>{const selection=getSelection();selection.removeAllRanges();if(c.kind==='fallback')return;const range=document.createRange();if(c.kind==='selected'){const text=node.querySelector('p').childNodes[1];range.setStart(text,1);range.setEnd(text,3);}else if(c.kind==='list'){range.setStart(node.querySelector('li').firstChild,1);range.collapse(true);}else range.selectNodeContents(node.querySelector('pre'));selection.addRange(range);},c);await page.getByRole('button',{name:'표',exact:true}).click();if(c.kind==='list'){const text=await page.locator('.rich-editor').evaluate(node=>{const clone=node.cloneNode(true);clone.querySelectorAll('table').forEach(n=>n.remove());return clone.textContent.replace(/\s/g,'');});assert.equal(text,'첫항목둘째항목끝');}await page.getByRole('button',{name:'Markdown 원문',exact:true}).click();const area=page.getByRole('textbox',{name:'Markdown 원문',exact:true}),value=await area.inputValue();if(['raw','code'].includes(c.kind)){assert.equal(value,c.source);assert.ok(!value.includes('| 항목 |'));continue;}assert.ok(value.includes('| 항목 | 내용 |'));if(c.kind==='selected'){assert.ok(value.includes('**앞**')&&value.includes('*뒤*')&&value.includes('끝'));assert.ok(!value.includes('선택'));}if(c.kind==='fallback')assert.ok(value.startsWith(c.source));await page.getByRole('button',{name:'실행 취소',exact:true}).click();assert.equal(await area.inputValue(),c.source);await page.getByRole('button',{name:'다시 실행',exact:true}).click();assert.equal(await area.inputValue(),value);await waitSaved();}});
