await check('delayed_shared_task_save_does_not_overwrite_other_project_title',async()=>{await page.setViewportSize({width:1440,height:1100});await page.locator('#project-search').fill('');await page.waitForFunction(()=>document.querySelectorAll('.project-item').length===2);const shared=fixture.tasks.find(x=>x.expected_state==='shared'),other=fixture.projects.find(x=>x.id!==project.id);await page.locator('[data-project-id="'+project.id+'"]').click();await page.waitForFunction(()=>document.getElementById('board').getAttribute('aria-busy')!=='true');await page.locator('[data-task-id="'+shared.id+'"]').click();await page.getByRole('textbox',{name:'위키 표시 이름'}).waitFor();const aWiki=await api('/api/tasks/'+shared.id+'/wiki?project_id='+project.id),bWiki=await api('/api/tasks/'+shared.id+'/wiki?project_id='+other.id);assert.equal(aWiki.status,200);assert.equal(bWiki.status,200);let committedResolve;const committed=new Promise(r=>committedResolve=r);const match='**/api/tasks/'+shared.id+'/wiki?project_id='+project.id,heldSave=await holdActualRoute(match,{postOnly:true,onFetched:async response=>{assert.equal(response.status(),200);committedResolve();}});const sent='A 프로젝트에만 저장한 공유 제목';await page.getByRole('textbox',{name:'위키 표시 이름'}).fill(sent);await committed;await page.locator('[data-project-id="'+other.id+'"]').click();await page.waitForFunction(id=>document.querySelector('.project-item[aria-pressed="true"]').dataset.projectId===id&&document.getElementById('board').getAttribute('aria-busy')!=='true',other.id);await page.locator('[data-task-id="'+shared.id+'"]').click();await page.getByRole('textbox',{name:'위키 표시 이름'}).waitFor();assert.equal(await page.getByRole('textbox',{name:'위키 표시 이름'}).inputValue(),bWiki.body.title);await heldSave.close();await page.waitForTimeout(350);assert.equal(await page.locator('#detail > h2').textContent(),bWiki.body.title);assert.ok(!(await page.locator('[data-task-id="'+shared.id+'"]').textContent()).includes(sent));assert.equal((await api('/api/tasks/'+shared.id+'/wiki?project_id='+project.id)).body.title,sent);assert.equal((await api('/api/tasks/'+shared.id+'/wiki?project_id='+other.id)).body.title,bWiki.body.title);await page.locator('[data-project-id="'+project.id+'"]').click();await page.waitForFunction(id=>document.querySelector('.project-item[aria-pressed="true"]').dataset.projectId===id&&document.getElementById('board').getAttribute('aria-busy')!=='true',project.id);});
await check('separate_server_restart_preserves_saved_markdown',async()=>{const response=await api('/api/projects/'+project.id+'/wiki');assert.equal(response.status,200);const before=response.body,file=localDocument(before),bytes=await fs.readFile(file);await page.close();await stopServer();fixture=await readyServer(true);token=decodeURIComponent(new URL(fixture.url).hash.slice(1));origin=new URL(fixture.url).origin;page=await browser.newPage();await page.goto(fixture.url);await page.locator('.project-item').first().waitFor();await page.waitForFunction(()=>document.getElementById('board').getAttribute('aria-busy')!=='true'&&document.querySelector('.column'));assert.deepEqual(await fs.readFile(file),bytes);const after=await api('/api/projects/'+project.id+'/wiki');assert.equal(after.status,200);assert.equal(after.body.title,before.title);assert.equal(after.body.body_markdown,before.body_markdown);assert.equal(after.body.revision,before.revision);await page.locator('[data-project-id="'+project.id+'"]').click();await page.waitForFunction(title=>document.getElementById('project-name').textContent===title,before.title);await page.getByRole('button',{name:'프로젝트 문서 편집',exact:true}).click();assert.equal(await page.getByRole('textbox',{name:'위키 표시 이름'}).inputValue(),before.title);});
