await check('reactflow_real_record_links_are_readonly_and_korean',async()=>{await page.locator('[data-task-id="'+task.id+'"]').click();await page.getByRole('tab',{name:'기록 흐름',exact:true}).click();await page.locator('.react-flow__node').first().waitFor();const actual=await api(scoped('/api/tasks/'+task.id));assert.equal(await page.locator('.react-flow__node').count(),1+actual.body.documents.length+actual.body.requests.length);assert.ok(await page.getByRole('button',{name:'확대',exact:true}).count());const node=page.locator('.react-flow__node').first(),before=await node.getAttribute('style'),box=await node.boundingBox();await page.mouse.move(box.x+20,box.y+15);await page.mouse.down();await page.mouse.move(box.x+90,box.y+65);await page.mouse.up();assert.equal(await node.getAttribute('style'),before);await page.screenshot({path:path.join(run,'actual-record-flow.png'),fullPage:true});});
