await check('history_view_is_partitioned_by_project_task_role_and_path',async()=>{const target=fixture.tasks.find(t=>t.expected_state==='history_scope');for(const p of fixture.projects){await page.locator('[data-project-id="'+p.id+'"]').click();await page.waitForFunction(()=>document.getElementById('board')?.getAttribute('aria-busy')!=='true');await selectTaskForMutation(target.id);const detail=(await api('/api/tasks/'+target.id+'?project_id='+p.id)).body;for(const role of ['interim','final']){const doc=detail.documents.find(d=>d.role===role||d.path.includes('/'+role+'/'));assert.ok(doc,role);const marker='실제 이력 원문 '+p.id+' '+role;const file=path.join(fixture.vault,doc.path);await fs.appendFile(file,'\n'+marker+'\n');await page.getByRole('tab',{name:role==='interim'?'중간 기록':'과거 완료 기록',exact:true}).click();assert.equal(await page.locator('#detail .markdown-preview').count(),0,'incompatible previous history remained');await page.getByRole('button',{name:path.basename(doc.path),exact:true}).click();await page.getByText(marker,{exact:true}).waitFor();assert.equal((await page.locator('#detail .markdown-preview').textContent()).includes(marker),true);}}});
