await check('human_respond_lost_ack_remains_close_unsafe_without_visible_draft',async()=>{const target=fixture.tasks.find(t=>t.expected_state==='review'&&t.project_id===fixture.projects[0].id);await page.locator('[data-project-id="'+target.project_id+'"]').click();await page.waitForFunction(()=>document.getElementById('board')?.getAttribute('aria-busy')!=='true');await selectTaskForMutation(target.id);await page.getByRole('tab',{name:'질문·답변',exact:true}).click();const rid='human-pending-close-'+target.id,input=page.locator('#response-'+rid),article=page.locator('.request').filter({has:input});let done,heldBoard;const received=new Promise(resolve=>done=resolve),match='**/api/requests/'+rid+'/respond?*';const lost=async route=>{heldBoard=await holdActualRoute('**/api/board?*',{beforeForward:true});const response=await route.fetch();assert.equal(response.status(),200);await input.fill('');assert.equal((await desktopCloseState()).state.safe,false);await route.abort('failed');done();};await page.route(match,lost);await input.fill('실제로 제출한 답변 A');await article.getByRole('button',{name:'답변 기록',exact:true}).click();await received;assert.equal((await desktopCloseState()).state.safe,false);await page.unroute(match,lost);await heldBoard.close();await page.getByRole('button',{name:'새로고침',exact:true}).click();await article.getByText('실제로 제출한 답변 A',{exact:true}).waitFor();assert.equal((await api('/api/requests/'+rid+'?project_id='+target.project_id)).body.record.response.text,'실제로 제출한 답변 A');assert.equal((await desktopCloseState()).state.safe,true);});
