await check('control_lost_ack_poll_retry_preserves_exact_operation_and_newer_draft',async()=>{await page.locator('[data-project-id="'+project.id+'"]').click();await page.waitForFunction(()=>document.getElementById('board')?.getAttribute('aria-busy')!=='true');await selectTaskForMutation(task.id);await page.getByRole('tab',{name:'실행 기록',exact:true}).click();const input=page.locator('#control-text-'+task.id),first='재접수하면 안 되는 A 원문',endpoint=scoped('/api/tasks/'+task.id+'/control');const readReceipts=()=>{const p=spawnSync(opts.python,['-c',"import sys,sqlite3,json;db=sqlite3.connect('file:'+sys.argv[1]+'?mode=ro',uri=True);print(json.dumps([json.loads(r[0]) for r in db.execute(\"SELECT body FROM records WHERE kind='board-control'\") if json.loads(r[0]).get('task_id')==sys.argv[2]],ensure_ascii=False))",path.join(fixture.knowledge_home,'knowledge.sqlite3'),task.id],{encoding:'utf8'});assert.equal(p.status,0,p.stderr);return JSON.parse(p.stdout)};const before=readReceipts().length;let heldBoard;let firstPayload,received;const done=new Promise(resolve=>received=resolve),matcher='**/api/tasks/'+task.id+'/control?*';const lost=async route=>{firstPayload=route.request().postDataJSON();heldBoard=await holdActualRoute('**/api/board?*',{beforeForward:true});const response=await route.fetch();assert.equal(response.status(),200);await route.abort('failed');received();};await page.route(matcher,lost);await input.fill(first);await page.getByRole('button',{name:'일시정지 요청',exact:true}).click();await done;await page.unroute(matcher,lost);for(let i=0;i<6;i++){const current=(await api(scoped('/api/tasks/'+task.id))).body;assert.equal((await api(endpoint,'POST',{operation_id:'independent-'+i+'-'+Date.now(),kind:'constraint',text:'별도 제약 '+i,expected_task_revision:current.control.task_revision,expected_control_version:current.control.control_version,expected_vault_revision:current.vault_revision})).status,200)}await heldBoard.close();await page.getByRole('button',{name:'새로고침',exact:true}).click();await page.waitForFunction(()=>document.getElementById('board')?.getAttribute('aria-busy')!=='true');assert.equal(await input.inputValue(),first);assert.equal((await desktopCloseState()).state.safe,false);let retryPayload;const retry=async route=>{retryPayload=route.request().postDataJSON();await route.continue()};await page.route(matcher,retry);await page.getByRole('button',{name:'일시정지 요청',exact:true}).click();await page.waitForFunction(id=>document.getElementById('control-text-'+id)?.value==='',task.id);await page.unroute(matcher,retry);assert.deepEqual(retryPayload,firstPayload);assert.equal(readReceipts().length,before+7);assert.equal(readReceipts().filter(r=>r.input.operation_id===firstPayload.operation_id).length,1);});
